{
  "case_id": "xsu_sg_002_permanence_requirement",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret har væsentlige juridiske mangler og fejl. Det nævner ikke vejledningens udgangspunkt om omkring et års varighed og symptomer eller følger i mindst et år før ansøgningen. Det fremstiller midlertidig funktionsnedsættelse som udgangspunkt ikke opfyldende, og at en senere kronisk tilstand \"ikke opfylder betingelsen\", hvilket er forvirrende og delvist forkert. Det udelader, at tidsbegrænset tillæg kan gives, når varighed er sandsynliggjort men ikke endeligt fastslået (§ 36, stk. 2). Det antyder desuden, at man kan miste grundlaget, fordi sygdommen er blevet kronisk, hvilket vender logikken om."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Element 1 (varighed vedrører art og grad) og element 2 (hverken af sig selv eller ved behandling væsentligt bedre inden for en længere årrække) er dækket, i hvert fald delvist. Element 3 (omkring et år / mindst et år før ansøgning) mangler helt. Element 4 (tidsbegrænset tillæg ved sandsynliggjort varighed) mangler også."
    },
    "c03_direct_relevance": {
      "label": "not_met",
      "reason": "Svaret besvarer første del om varighed. Anden del, hvad der gælder hvis tilstanden ikke er varig/kronisk fra begyndelsen, besvares ikke i sagen: det nævner hverken étårsvurderingen eller muligheden for tidsbegrænset tillæg. Det erstattes af generel tekst om midlertidighed og om at søge igen."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Svaret henviser med nummererede noter til identificerbare kilder: SU-loven § 7, stk. 3, forarbejder (L 182) og tre afgørelser fra Ankenævnet. Der er dog en markering \"(uden kilde)\" i konklusionen, men de væsentlige udsagn er knyttet til kilder."
    },
    "c05_source_validity": {
      "label": "not_met",
      "reason": "Svaret citerer ikke de autoritative kilder, der dækker kerneudsagnene, nemlig vejledningen afsnit 3.4.1.1 og SU-bekendtgørelsen § 36, stk. 2. Det støtter sig i stedet på forarbejder til en \"senere SU-reform\", dvs. L 182, og ældre nævnsafgørelser fra 2013 og 2019. Disse er ikke de aktuelle autoritative kilder i den frosne afgrænsning. Systemet selv markerer \"uverificerede kilder\"."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "Flere påstande støttes ikke af de angivne kilder. Lovteksten i § 7, stk. 3 støtter ikke påstanden om, at midlertidig funktionsnedsættelse som udgangspunkt ikke opfylder kravet, eller muligheden for at søge igen (note 5). De konkrete nævnsafgørelser støtter ikke de generelle udsagn om, at praksis viser, at en lidelse kan være varig selv om behandling pågår, og at senere kronisk udvikling får støtten til at falde væk. Selve udsagnet i konklusionen er markeret \"uden kilde\"."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer regler uden støtte i materialet, bl.a. at en studerende kan miste grundlaget for ekstra støtte, når sygdommen bliver kronisk, og at man kan søge igen på nyt grundlag ved væsentlig forværring. Det fremstiller varighed som et prognosespørgsmål om \"overskuelig længere tid\" og tilføjer krav om \"tilstrækkelig lægelig dokumentation\" for at tilstanden ikke kan bedres. Dette er delvist støttet af § 37, men er ikke knyttet til den kilde."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Kvalifikationerne om \"omkring et år\" og \"som udgangspunkt\" i forhold til symptomer før ansøgning mangler. Forbeholdet om, at tidsbegrænset tillæg forudsætter sandsynliggjort varighed, mangler også. Svaret bevarer \"som udgangspunkt\" andre steder, men ikke de kvalifikationer, som rubrikken kræver."
    },
    "c09_reasoning_coherence": {
      "label": "not_met",
      "reason": "Svaret er internt modstridende. Det siger, at en tilstand, der \"først senere er blevet kronisk/varig\", ikke opfylder betingelsen, men samtidig at varig/kronisk tilstand er det, der kræves. Det siger også, at en studerende kan miste støtten, fordi sygdommen er blevet kronisk, hvilket vender logikken om. Konklusionen følger derfor ikke af de angivne trin."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Modaliteten er upræcis. Konklusionen siger, at betingelsen \"ikke er opfyldt\", hvis tilstanden kun er midlertidig eller først senere er blevet varig, hvilket gør et udgangspunkt til en absolut regel og ignorerer, at vejledningen taler om omkring et år. Udtrykket \"mest nærliggende\" er i øvrigt hedgende, men det retter ikke den absolutte formulering. Svaret gengiver ikke § 36, stk. 2's \"kan\" om tidsbegrænset tillæg."
    }
  },
  "xhaile_coverage": {
    "A9": {
      "label": "yes",
      "reason": "Svaret fastslår, at funktionsnedsættelsen skal være varig, og redegør for, hvordan varighed vurderes, jf. § 7, stk. 3 og vejledningens definition."
    },
    "A12": {
      "label": "no",
      "reason": "Svaret nævner ikke, at en ikke-varig funktionsnedsættelse kan vurderes varig efter omkring et år, og heller ikke at symptomer eller følger som udgangspunkt skal have varet mindst et år før ansøgningen. Det siger tværtimod, at midlertidige tilstande som udgangspunkt ikke opfylder kravet."
    }
  },
  "overall_notes": "Svaret rammer kernen i varighedskriteriet (ikke væsentligt bedre inden for en længere årrække), men mangler de to centrale elementer for spørgsmålets anden del: étårsvurderingen og tidsbegrænset tillæg ved sandsynliggjort varighed. Det er desuden internt modstridende om kronisk udvikling og støtter sig på forarbejder og nævnspraksis i stedet for vejledningen og bekendtgørelsen. Svaret har selv markeret begrænset pålidelighed."
}

